import { FormEvent, useContext, useState } from 'react';

import cn from 'clsx';
import { Link } from 'react-router-dom';

import { login } from '@apps/Account/@services/authService';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';

import { AuthContext, IAuthContext } from '../../../../contexts/AuthContext';

interface ILoginUsernamePasswordFormProps {
  onEnd: IAuthContext['onLogin'];
  className?: string;
  redirectTo: string;
  login: string;
}

function LoginUsernamePasswordForm({
  onEnd,
  className,
  redirectTo,
  login: loginFromProps,
}: ILoginUsernamePasswordFormProps) {
  const [username, setUsername] = useState(loginFromProps);
  const [password, setPassword] = useState('');
  const { onLogin } = useContext(AuthContext);

  const submitFormHandler = (e: FormEvent) => {
    e.preventDefault();
    login({ username, password }).then((result) => {
      if (result && result.userId) {
        onLogin?.({ id: +result.userId, hash: result.hash }, onEnd);
      }
    });
  };

  return (
    <>
      <form onSubmit={submitFormHandler} className={cn('mt-4', 'qa-loginForm', className)}>
        <PohInput
          placeholder="Введите логин"
          required
          value={username}
          name="username"
          id="username"
          onChange={setUsername}
          className="mb-1"
        />
        <PohInput
          type={InputTypes.password}
          placeholder="Введите пароль"
          required
          value={password}
          name="password"
          id="password"
          onChange={setPassword}
          className="mb-2"
        />

        <PohButton
          variant={ButtonVariant.Primary}
          onClick={() => {}}
          className="w-100"
          type="submit"
        >
          Войти
        </PohButton>
      </form>
      <p className="d-flex align-items-center justify-content-between">
        <Link to={`/reg?return=${redirectTo}`}>РЕГИСТРАЦИЯ</Link>
        <Link to={`/recovery?login=${username}&return=${redirectTo}`}>Забыли пароль?</Link>
      </p>
    </>
  );
}

export default LoginUsernamePasswordForm;
