import cn from 'clsx';

import PohButton, { ButtonVariant } from '@ui-kit/Button';
import { confirmModal } from '@ui-kit/Modal';

import style from './style.module.less';
import { IAuthContext } from '../../../../../contexts/AuthContext';
import { socialAuthGo } from '../socialAuthHelper';

interface ISocialProviderCardProps {
  id: string;
  name: string;
  link: string;
  color: string;
  iconComponent: string;
  onLogin: IAuthContext['onLogin'];
  afterLogin: IAuthContext['onLogin'];
  problemsMode?: boolean;
}

const SocialProviderCard = ({
  color,
  name,
  link,
  iconComponent: Icon,
  onLogin,
  afterLogin,
  id,
  problemsMode = false,
}: ISocialProviderCardProps) => (
  <PohButton
    onClick={async () => {
      problemsMode &&
        (await confirmModal({
          children: (
            <div>
              <p>В настоящее время наблюдаются проблемы со входом на сайт через внешние сайты.</p>
              <p>
                Авторизуйтесь как привыкли, а затем на странице профиля добавьте вход по
                логину/паролю
              </p>
              <p>Вы будете попадать в один и тот же профиль разными способами</p>
            </div>
          ),
          title: 'Внимание',
        }));

      socialAuthGo(link, onLogin, afterLogin);
    }}
    className={cn(style.socCard, 'mb-1 w-100 b-1', 'qa-social-auth-btn', `qa-social-auth-${id}`)}
    variant={ButtonVariant.Light}
  >
    <span className={style.icon} style={{ backgroundColor: color }}>
      <Icon />
    </span>
    <span>Войти через {name}</span>
    <em />
  </PohButton>
);

export default SocialProviderCard;
