import React from 'react';

import ShieldExclamation from '@pohodnik/icons/svg/Security/ShieldExclamation';
import cn from 'clsx';
import queryString from 'query-string';
import { useLocation, useNavigate } from 'react-router-dom';

import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import ExternalApp from './ExternalApp';
import LoginUsernamePasswordForm from './LoginUsernamePasswordForm';
import SocialAuth from './SocialAuth';
import style from './style.module.less';
import { IAuthContext } from '../../../contexts/AuthContext';
import { IExternalSystem } from '../@types/auth.types';

const Login = () => {
  const history = useLocation();
  const navigate = useNavigate();
  const search = queryString.parse(history.search) || {};
  const afterAuthRedirectUrl = (search.return || search.rel || '/') as string;
  const loginFromUrl = (search.login || '') as string;
  const clientId = (search.client_id || '') as string;
  const redirectUrl = (search.redirect_url || search.redirect_uri || '') as string;
  const [_externalAppData, setExternalAppData] = React.useState<IExternalSystem | null>(null);

  const [showExternalAppInfo, setShowExternalAppInfo] = React.useState(false);

  const handleEnd: IAuthContext['onLogin'] = (d) => {
    if (redirectUrl.length) {
      const urlForRedirect = redirectUrl.includes('?')
        ? `${redirectUrl}&token=${d.hash}`
        : `${redirectUrl}?token=${d.hash}`;

      window.location.href = urlForRedirect;
    } else {
      navigate(afterAuthRedirectUrl);
    }
    //
    // if (externalAppData?.callback) {
    //     window.location.href = externalAppData.callback.includes('?') ? `${externalAppData.callback}&token=${d.user.hash}` : `${externalAppData.callback}?token=${d.user.hash}`;
    // }
  };

  return (
    <PohContainer>
      <PohRow>
        <PohCol
          xl={{ span: 4, offset: 4 }}
          lg={{ span: 6, offset: 3 }}
          md={{ span: 8, offset: 2 }}
          sm={{ span: 12 }}
        >
          <div className="text-center mb-4">
            <h3>
              Войдите в аккаунт{' '}
              {clientId && (
                <ShieldExclamation
                  className="text-warning ms-2"
                  onClick={() => setShowExternalAppInfo((c) => !c)}
                />
              )}
            </h3>
            {clientId && showExternalAppInfo && (
              <ExternalApp clientId={clientId} onData={setExternalAppData} />
            )}
            <p>Авторизуйтесь используя учетную запись</p>
          </div>
          <SocialAuth onEnd={handleEnd} />
          <div className={cn(style.divider, 'mt-3')}>или</div>
          <LoginUsernamePasswordForm
            onEnd={handleEnd}
            redirectTo={afterAuthRedirectUrl}
            login={loginFromUrl}
          />
        </PohCol>
      </PohRow>
    </PohContainer>
  );
};

export default Login;
